from itertools import product

# Generate all possible binary sequences of length 21
sequences = list(product([-1, 1], repeat=21))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[5] == -1 and seq[12] == -1 and seq[17] == 1 and seq[20] == 1:
        c = [0] * 21
        for k in range(1, 21):
            for i in range(21 - k):
                c[k-1] += seq[i] * seq[i + k]
        if c[0] == 2 and c[1] == -1 and c[8] == 2 and c[19] == -1:
            valid_sequences.append(seq)

# Check if any valid sequence has low aperiodic autocorrelation
solutions = []
for seq in valid_sequences:
    c = [0] * 21
    for k in range(1, 21):
        for i in range(21 - k):
            c[k-1] += seq[i] * seq[i + k]
    if sum([x**2 for x in c]) <= 52 + c[0]**2:
        solutions.append(seq)

if solutions:
    print(solutions[0])
else:
    print("UNSATISFIABLE")
